import {test} from 'node:test';
import assert from 'node:assert/strict';
import {verdict, validate} from '../src/audit.mjs';

test('verdict returns PASSED when all checks passed', () => {
  assert.equal(verdict([{status: 'passed'}]), 'PASSED');
  assert.equal(verdict([{status: 'passed'}, {status: 'passed'}]), 'PASSED');
});

test('verdict returns INCONCLUSIVE on empty checks', () => {
  assert.equal(verdict([]), 'INCONCLUSIVE');
});

test('verdict returns INCONCLUSIVE if any check is not passed', () => {
  assert.equal(verdict([{status: 'timeout'}]), 'INCONCLUSIVE');
  assert.equal(verdict([{status: 'passed'}, {status: 'execution-error'}]), 'INCONCLUSIVE');
  assert.equal(verdict([{status: 'passed'}, {status: 'output-limit'}]), 'INCONCLUSIVE');
});

test('validate rejects non-sha256 image', () => {
  assert.throws(() => validate({image: 'node:latest', checks: [{name: 'a', argv: ['node'], timeoutMs: 1000}]}), /Immutable local image/);
  assert.throws(() => validate({image: 'sha256:xyz', checks: []}), /Immutable local image/);
});

test('validate accepts valid sha256 image', () => {
  const img = 'sha256:' + 'a'.repeat(64);
  assert.doesNotThrow(() => validate({image: img, checks: [{name: 'unit', argv: ['node', '--test'], timeoutMs: 10000}]}));
});

test('validate rejects empty or >10 checks', () => {
  const img = 'sha256:' + 'b'.repeat(64);
  assert.throws(() => validate({image: img, checks: []}), /1–10 checks/);
  const many = Array.from({length: 11}, (_, i) => ({name: 'c' + i, argv: ['true'], timeoutMs: 1000}));
  assert.throws(() => validate({image: img, checks: many}), /1–10 checks/);
});

test('validate rejects duplicate check names', () => {
  const img = 'sha256:' + 'c'.repeat(64);
  assert.throws(() => validate({image: img, checks: [{name: 'dup', argv: ['true'], timeoutMs: 1000}, {name: 'dup', argv: ['true'], timeoutMs: 1000}]}), /duplicate name/i);
});

test('validate rejects invalid timeout', () => {
  const img = 'sha256:' + 'd'.repeat(64);
  assert.throws(() => validate({image: img, checks: [{name: 't1', argv: ['true'], timeoutMs: 50}]}), /Invalid timeout/);
  assert.throws(() => validate({image: img, checks: [{name: 't2', argv: ['true'], timeoutMs: 200000}]}), /Invalid timeout/);
});

test('validate rejects argv with null bytes', () => {
  const img = 'sha256:' + 'e'.repeat(64);
  assert.throws(() => validate({image: img, checks: [{name: 'n', argv: ['true\0bad'], timeoutMs: 1000}]}));
});

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {repositoryURL} from '../src/repository.mjs';

test('accepts valid GitHub HTTPS URL', () => {
  assert.equal(repositoryURL('https://github.com/gilvanecesar/obra-qa'), 'https://github.com/gilvanecesar/obra-qa.git');
});

test('accepts .git suffix and strips trailing slash', () => {
  assert.equal(repositoryURL('https://github.com/user/repo.git'), 'https://github.com/user/repo.git');
  assert.equal(repositoryURL('https://github.com/user/repo/'), 'https://github.com/user/repo.git');
});

test('rejects HTTP protocol', () => {
  assert.throws(() => repositoryURL('http://github.com/a/b'));
});

test('rejects embedded credentials', () => {
  assert.throws(() => repositoryURL('https://user:secret@github.com/a/b'));
});

test('rejects non-GitHub host', () => {
  assert.throws(() => repositoryURL('https://gitlab.com/a/b'));
  assert.throws(() => repositoryURL('https://localhost/a/b'));
});

test('rejects branch paths and query strings', () => {
  assert.throws(() => repositoryURL('https://github.com/a/b/tree/main'));
  assert.throws(() => repositoryURL('https://github.com/a/b?token=x'));
});

test('rejects path traversal in pathname', () => {
  assert.throws(() => repositoryURL('https://github.com/a/..'));
  assert.throws(() => repositoryURL('https://github.com/./b'));
});

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {resolveRevision, inspectProject} from '../src/project.mjs';

test('resolveRevision returns 40-char hex SHA', () => {
  const dir = mkdtempSync(join(tmpdir(), 'qa-proj-'));
  const git = (...a) => execFileSync('git', ['-C', dir, ...a], {stdio: 'pipe'});
  try {
    git('init');
    git('config', 'user.name', 'QA');
    git('config', 'user.email', 'qa@example.invalid');
    writeFileSync(join(dir, 'README.md'), '# Test');
    git('add', '.');
    git('commit', '-m', 'init');
    const sha = resolveRevision(dir);
    assert.match(sha, /^[a-f0-9]{40}$/);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});

test('inspectProject reads committed README, ignores uncommitted changes', () => {
  const dir = mkdtempSync(join(tmpdir(), 'qa-proj-'));
  const git = (...a) => execFileSync('git', ['-C', dir, ...a], {stdio: 'pipe'});
  try {
    git('init');
    git('config', 'user.name', 'QA');
    git('config', 'user.email', 'qa@example.invalid');
    writeFileSync(join(dir, 'README.md'), 'Committed content');
    git('add', '.');
    git('commit', '-m', 'init');
    const sha = resolveRevision(dir);
    writeFileSync(join(dir, 'README.md'), 'UNCOMMITTED PRIVATE');
    const result = inspectProject(dir, sha);
    assert.equal(result.documentation[0].text, 'Committed content');
    assert.equal(result.revision, sha);
    assert.ok(result.trackedFiles >= 1);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createBridge} from '../src/bridge.mjs';

const token = 'x'.repeat(48);
const sha = 'b'.repeat(40);
const spec = {image: 'sha256:' + 'c'.repeat(64), checks: [{name: 'unit', argv: ['node', '--test'], timeoutMs: 10000}]};

test('bridge rejects unauthorized requests with 401', async () => {
  const s = createBridge({token, projects: {demo: {repo: '/x', spec}}});
  await new Promise(r => s.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${s.address().port}`;
  try {
    const res = await fetch(url + '/projects', {headers: {authorization: 'Bearer wrong'}});
    assert.equal(res.status, 401);
    const res2 = await fetch(url + '/projects');
    assert.equal(res2.status, 401);
  } finally { s.closeAllConnections(); await new Promise(r => s.close(r)); }
});

test('bridge returns project list on GET /projects', async () => {
  const s = createBridge({token, projects: {demo: {repo: '/x', spec}, alpha: {repo: '/y', spec}}});
  await new Promise(r => s.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${s.address().port}`;
  try {
    const res = await fetch(url + '/projects', {headers: {authorization: `Bearer ${token}`}});
    assert.equal(res.status, 200);
    const body = await res.json();
    assert.deepEqual(body, {projects: ['demo', 'alpha']});
  } finally { s.closeAllConnections(); await new Promise(r => s.close(r)); }
});

test('bridge serializes concurrent jobs with 409', async () => {
  let finish;
  const runner = () => new Promise(r => { finish = r; });
  const s = createBridge({token, projects: {demo: {repo: '/x', spec}}, runner});
  await new Promise(r => s.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${s.address().port}`;
  const headers = {authorization: `Bearer ${token}`, 'content-type': 'application/json'};
  try {
    const r1 = await fetch(url + '/jobs', {method: 'POST', headers, body: JSON.stringify({project: 'demo', revision: sha})});
    assert.equal(r1.status, 202);
    const r2 = await fetch(url + '/jobs', {method: 'POST', headers, body: JSON.stringify({project: 'demo', revision: sha})});
    assert.equal(r2.status, 409);
    finish({report: {verdict: 'PASSED'}});
    await new Promise(r => setImmediate(r));
  } finally { s.closeAllConnections(); await new Promise(r => s.close(r)); }
});

test('bridge rejects path traversal project names', async () => {
  const s = createBridge({token, projects: {demo: {repo: '/x', spec}}});
  await new Promise(r => s.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${s.address().port}`;
  const headers = {authorization: `Bearer ${token}`, 'content-type': 'application/json'};
  try {
    const r = await fetch(url + '/jobs', {method: 'POST', headers, body: JSON.stringify({project: '../private', revision: sha})});
    assert.equal(r.status, 400);
  } finally { s.closeAllConnections(); await new Promise(r => s.close(r)); }
});

test('bridge rejects browser origins with 403', async () => {
  const s = createBridge({token, projects: {demo: {repo: '/x', spec}}});
  await new Promise(r => s.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${s.address().port}`;
  try {
    const res = await fetch(url + '/projects', {headers: {authorization: `Bearer ${token}`, origin: 'https://evil.com'}});
    assert.equal(res.status, 403);
  } finally { s.closeAllConnections(); await new Promise(r => s.close(r)); }
});
